using AcmeStub;

var builder = WebApplication.CreateBuilder(args);

// the API key arrives as a file, generated by compose.yml on the first docker compose up
builder.Configuration.AddKeyPerFile("/secrets", optional: true);

builder.Services.AddSingleton(TimeProvider.System);
builder.Services.AddSingleton<Gateway>();

var app = builder.Build();

app.MapPost("/api/payment", (HttpContext context, Gateway gateway) => gateway.SubmitPaymentAsync(context));
app.MapGet("/apirttq/query/Merchant/{merchantId}", (HttpContext context, string merchantId, Gateway gateway) =>
    gateway.QueryTransaction(context, merchantId));

// made before the first request, so a missing API key or merchant id stops the stub at start
app.Services.GetRequiredService<Gateway>();

app.Run();
